(()=>{
 const q=s=>document.querySelector(s),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let options,tab='accounts',page=1,search='',status='',rows=[],editing,submit;
 const label=s=>s.replaceAll('_',' ').replaceAll('.',' · ').replace(/\b\w/g,c=>c.toUpperCase());
 const date=v=>v?new Date(v).toLocaleString():'Never';
 async function api(path,method='GET',data){const r=await fetch(path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)}),d=await r.json();if(r.status===401){location.replace('/login');throw Error('Please sign in.');}if(d.code==='ACCOUNT_SECURITY_REQUIRED')location.replace('/account-security');if(!r.ok)throw Error(d.message||'Request failed.');return d;}
 function systemControls(){q('#admin-content').insertAdjacentHTML('beforeend',`<fieldset class="admin-section"><legend>System Features</legend><div class="admin-checks">${['assets','barcode','inventory','technical','warranty','repairs','refresh','disposal','security','finance','exports'].map(f=>`<label><input type="checkbox" data-feature="${f}" ${options.settings.find(s=>s.setting_key==='feature:'+f)?.setting_value==='0'?'':'checked'}>${e(label(f))}</label>`).join('')}</div></fieldset><fieldset class="admin-section"><legend>Purge Inactive Master Record</legend><p class="small">Only inactive records without references may be permanently removed. Account records, asset history, transactions, and audit logs are retained.</p><form id="purge-form"><label>Table<select name="table">${['asset_categories','asset_types','asset_classes','manufacturers','asset_models','asset_conditions','units_of_measure'].map(t=>`<option value="${t}">${e(label(t))}</option>`).join('')}</select></label><label>Record ID<input name="id" type="number" min="1" required></label><label>Type PURGE to confirm<input name="confirm" pattern="PURGE" required autocomplete="off"></label><button class="danger">Permanently Purge Record</button></form></fieldset>`);q('#purge-form').onsubmit=async ev=>{ev.preventDefault();try{const data=Object.fromEntries(new FormData(ev.target));if(data.confirm!=='PURGE')throw Error('Type PURGE to confirm.');await api('/api/admin/purge','POST',data);message('Inactive master record purged and logged.');ev.target.reset();}catch(x){message(x.message);}};}
 function message(s){q('#admin-message').textContent=s;q('#admin-message').hidden=false;}
 function getName(row,t){return t==='employees'?`${row.employee_number} · ${row.first_name} ${row.last_name}`:row.role_name||row.business_unit_name||row.department_name||row.location_name||row.team_name;}
 const keys={employees:'employee_id',roles:'role_id',business_units:'business_unit_id',departments:'department_id',locations:'location_id',teams:'team_id'};
 function select(t,name,value,required=false){return `<select name="${name}" ${required?'required':''}><option value="">Select…</option>${options[t].map(a=>`<option value="${a[keys[t]]}" ${String(value)===String(a[keys[t]])?'selected':''}>${e(getName(a,t))}</option>`).join('')}</select>`;}
 function input(name,text,value='',type='text',required=false){return `<label>${text}<input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='password'?'minlength="8" maxlength="256" autocomplete="new-password"':'maxlength="254"'}></label>`;}
 function check(name,text,on){return `<label><input type="checkbox" name="${name}" ${on?'checked':''}>${text}</label>`;}
 function open(title,html,handler,save='Save'){q('#user-dialog-title').textContent=title;q('#user-fields').innerHTML=html;q('#user-error').hidden=true;submit=handler;q('#user-save').hidden=!handler;q('#user-save').textContent=save;if(!q('#user-dialog').open)q('#user-dialog').showModal();}
 function scopeRow(s={scope_type:'SITE',access_level:'VIEW'}){return `<div class="scope-row"><select aria-label="Scope type" data-scope-type>${['ENTERPRISE','BUSINESS_UNIT','SITE','DEPARTMENT','TEAM','SELF','COST_CENTER'].filter(v=>v!=='COST_CENTER').map(v=>`<option value="${v}" ${s.scope_type===v?'selected':''}>${label(v)}</option>`).join('')}</select><select aria-label="Scope reference" data-scope-ref data-selected="${e(s.scope_reference_id||'')}"></select><select aria-label="Scope access" data-scope-access><option value="VIEW" ${s.access_level==='VIEW'?'selected':''}>View</option><option value="MANAGE" ${s.access_level==='MANAGE'?'selected':''}>Manage</option></select><button type="button" data-remove-scope>Remove</button></div>`;}
 function scopeReferences(row){const type=row.querySelector('[data-scope-type]').value,ref=row.querySelector('[data-scope-ref]'),t={SITE:'locations',BUSINESS_UNIT:'business_units',DEPARTMENT:'departments',TEAM:'teams'}[type],v=ref.dataset.selected;ref.disabled=!t;ref.innerHTML=t?`<option value="">Select…</option>${options[t].map(a=>`<option value="${a[keys[t]]}" ${String(v)===String(a[keys[t]])?'selected':''}>${e(getName(a,t))}</option>`).join('')}`:'<option value="">No reference needed</option>';}
 function preview(){const roleIDs=[...q('#user-form').querySelectorAll('[name=role_ids]:checked')].map(x=>Number(x.value)),ids=new Set(options.role_permissions.filter(x=>roleIDs.includes(x.role_id)).map(x=>x.permission_id));q('#user-form').querySelectorAll('[data-permission]').forEach(x=>{if(x.value==='ALLOW')ids.add(Number(x.dataset.permission));if(x.value==='DENY')ids.delete(Number(x.dataset.permission));});q('#permission-preview').textContent=roleIDs.some(id=>options.roles.find(r=>r.role_id===id)?.role_code==='SUPER_ADMIN')?'Full system access · Enterprise-wide':options.permissions.filter(p=>ids.has(p.permission_id)).map(p=>label(p.permission_code)).join(', ')||'No effective permissions. Assign a role or explicit permission.';}
 async function editUser(id){editing=id?(await api('/api/admin/users/'+id)).user:null;const a=editing||{};open(id?'Edit User':'Create User',`<div class="admin-grid">${input('first_name','First Name',a.first_name||'','text',true)}${input('last_name','Last Name',a.last_name||'','text',true)}<label>Employee ID${select('employees','employee_id',a.employee_id)}</label>${input('username','Username',a.username||'','text',true)}${input('email','Email',a.email||'','email',true)}<label>Department${select('departments','department_id',a.department_id)}</label><label>Business Unit${select('business_units','business_unit_id',a.business_unit_id)}</label><label>Site${select('locations','site_id',a.site_id)}</label><label>Account Status<select name="is_active"><option value="1" ${a.is_active!==0?'selected':''}>Active</option><option value="0" ${a.is_active===0?'selected':''}>Inactive</option></select></label>${!id?input('temporary_password','Temporary Password','','password',true):''}</div><div class="admin-checks">${check('mfa_required','MFA Required',!!a.mfa_required)}${check('force_password_change','Force Password Change on Next Login',id?!!a.force_password_change:true)}</div><fieldset class="admin-section"><legend>Roles</legend><div class="admin-checks">${options.roles.filter(r=>r.is_active).map(r=>`<label><input name="role_ids" type="checkbox" value="${r.role_id}" ${a.roles?.some(x=>x.role_id===r.role_id)?'checked':''}>${e(r.role_name)}</label>`).join('')}</div></fieldset><fieldset class="admin-section"><legend>Access Scope</legend><p class="small">Permissions determine the action. Scope determines which records it applies to. Super Admin always has enterprise-wide access.</p><div id="scope-rows">${(a.scopes||[]).map(scopeRow).join('')}</div><button type="button" id="add-scope">Add Scope</button></fieldset><fieldset class="admin-section"><legend>Permission Overrides</legend><p class="small">Inherit uses the selected roles. Deny takes precedence across roles. Super Admin retains full access.</p>${options.permissions.map(p=>`<div class="permission-row"><label for="permission-${p.permission_id}">${e(label(p.permission_code))}</label><select id="permission-${p.permission_id}" data-permission="${p.permission_id}">${['INHERIT','ALLOW','DENY'].map(v=>`<option value="${v}" ${v===(a.overrides?.find(o=>o.permission_id===p.permission_id)?.effect||'INHERIT')?'selected':''}>${label(v)}</option>`).join('')}</select></div>`).join('')}</fieldset><fieldset class="admin-section"><legend>Effective Permissions</legend><div id="permission-preview" class="permission-preview"></div></fieldset>`,async form=>{const data=Object.fromEntries(new FormData(form));data.is_active=Number(data.is_active);data.mfa_required=form.mfa_required.checked;data.force_password_change=form.force_password_change.checked;data.role_ids=[...form.querySelectorAll('[name=role_ids]:checked')].map(x=>Number(x.value));data.scopes=[...form.querySelectorAll('.scope-row')].map(row=>({scope_type:row.querySelector('[data-scope-type]').value,scope_reference_id:row.querySelector('[data-scope-ref]').value||null,access_level:row.querySelector('[data-scope-access]').value}));data.overrides=[...form.querySelectorAll('[data-permission]')].filter(x=>x.value!=='INHERIT').map(x=>({permission_id:Number(x.dataset.permission),effect:x.value}));if(id)data.revision=a.revision;await api('/api/admin/users'+(id?'/'+id:''),id?'PATCH':'POST',data);message(id?'User updated. Existing sessions were revoked when access changed.':'User created. Share the temporary password securely.');await load();});q('#scope-rows').querySelectorAll('.scope-row').forEach(scopeReferences);q('#add-scope').onclick=()=>{q('#scope-rows').insertAdjacentHTML('beforeend',scopeRow());scopeReferences(q('#scope-rows').lastElementChild);};preview();}
 function actions(a){return `<div class="record-actions">${[['view','View'],['edit','Edit'],['status',a.is_active?'Deactivate':'Activate'],['reset','Reset Password'],['unlock','Unlock Account'],['roles','Assign Role'],['permissions','Change Permissions'],['activity','Review Activity'],['mfa','Reset MFA']].map(([key,title])=>`<button data-user-action="${key}" data-user="${a.user_id}">${title}</button>`).join('')}</div>`;}
 async function accounts(){const result=await api(`/api/admin/users?q=${encodeURIComponent(search)}&status=${status}&page=${page}`);rows=result.users;const cols=[['user_id','User ID'],['name','Full Name'],['username','Username'],['email','Email'],['employee_number','Employee ID'],['roles','Role'],['department_name','Department'],['site_name','Site'],['scopes','Access Scope'],['status','Account Status'],['last_login_at','Last Login'],['mfa','MFA Status'],['created_at','Date Created'],['actions','Actions']];const value=(a,k)=>k==='name'?e([a.first_name,a.last_name].filter(Boolean).join(' ')||'Not set'):k==='roles'?e(a.roles.map(r=>r.role_name).join(', ')||'No roles'):k==='scopes'?e(a.roles.some(r=>r.role_code==='SUPER_ADMIN')?'Enterprise · Manage':a.scopes.map(s=>`${label(s.scope_type)}${s.scope_reference_id?' · '+(getName((options[{SITE:'locations',BUSINESS_UNIT:'business_units',DEPARTMENT:'departments',TEAM:'teams'}[s.scope_type]]||[]).find(a=>a[keys[{SITE:'locations',BUSINESS_UNIT:'business_units',DEPARTMENT:'departments',TEAM:'teams'}[s.scope_type]]]===s.scope_reference_id)||{},'scope')||'#'+s.scope_reference_id):''} · ${label(s.access_level)}`).join(', ')||'No access scope'):k==='status'?e(a.is_active?(a.locked_until&&new Date(a.locked_until)>new Date()?'Locked':'Active'):'Inactive'):k==='mfa'?e(a.mfa_enabled?'Enrolled':a.mfa_required?'Required · Not enrolled':'Not required'):k==='last_login_at'||k==='created_at'?e(date(a[k])):k==='actions'?actions(a):e(a[k]??'—');q('#admin-content').innerHTML=`<div class="toolbar"><input id="user-search" type="search" aria-label="Search users" placeholder="Search name, username, or email" value="${e(search)}"><select id="user-status" aria-label="Account status"><option value="">All accounts</option>${['active','inactive','locked'].map(s=>`<option value="${s}" ${s===status?'selected':''}>${label(s)}</option>`).join('')}</select><button id="reload-users">Refresh</button></div><p class="small">${result.total} accounts</p>${rows.length?`<div class="table-scroll"><table class="records-data-table admin-table" role="table"><thead><tr>${cols.map(c=>`<th scope="col">${c[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(a=>`<tr>${cols.map(([key,title])=>`<td data-label="${title}"><span>${value(a,key)}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No users found.</div>'}<div class="admin-pagination"><button id="users-prev" ${page===1?'disabled':''}>Previous</button><span>Page ${page}</span><button id="users-next" ${page*50>=result.total?'disabled':''}>Next</button></div>`;let timer;q('#user-search').oninput=x=>{search=x.target.value;clearTimeout(timer);timer=setTimeout(()=>{page=1;load();},400);};q('#user-status').onchange=x=>{status=x.target.value;page=1;load();};q('#reload-users').onclick=load;q('#users-prev').onclick=()=>{page--;load();};q('#users-next').onclick=()=>{page++;load();};}
 function eventHTML(a){return `<article class="activity-event"><strong>${e(label(a.action))}</strong><p>${e(date(a.event_timestamp))} · By ${e(a.actor||'System / anonymous')} · ${e(a.module)} #${e(a.record_id)} · IP ${e(a.ip_address||'Unavailable')}</p><details><summary>Previous and new values</summary><pre>${e(JSON.stringify({previous:a.old_values?JSON.parse(a.old_values):null,new:a.new_values?JSON.parse(a.new_values):null},null,2))}</pre></details></article>`;}
 async function activity(id){const d=await api(`/api/admin/users/${id}/activity`);open('Account Activity',`<div id="activity-events">${d.events.map(eventHTML).join('')||'<p>No activity recorded.</p>'}</div><button type="button" id="more-activity" ${d.events.length<100?'hidden':''}>Load Older Activity</button>`,null);let cursor=d.events.at(-1)?.audit_id;q('#more-activity').onclick=async()=>{try{const next=await api(`/api/admin/users/${id}/activity?before=${cursor}`);q('#activity-events').insertAdjacentHTML('beforeend',next.events.map(eventHTML).join(''));cursor=next.events.at(-1)?.audit_id;q('#more-activity').hidden=next.events.length<100;}catch(x){message(x.message);}};}
 async function userAction(action,id){const a=rows.find(u=>u.user_id===id)||(await api('/api/admin/users/'+id)).user;if(['edit','roles','permissions'].includes(action)){await editUser(id);if(action==='permissions')q('#user-dialog .permission-row').scrollIntoView();return;}if(action==='activity')return activity(id);if(action==='view'){const info={...a};delete info.effective_permissions;open('User Details',`<dl class="admin-summary">${Object.entries(info).map(([k,v])=>`<dt>${e(label(k))}</dt><dd>${e(typeof v==='object'?JSON.stringify(v):v??'—')}</dd>`).join('')}</dl><h3>Effective permissions</h3><div class="permission-preview">${e(a.roles.some(r=>r.role_code==='SUPER_ADMIN')?'Full system access':a.effective_permissions.join(', ')||'None')}</div>`,null);return;}
 if(action==='reset'){open('Reset Password',`<p>Reset the password for <strong>${e(a.username)}</strong>. All sessions will end and a password change will be required at next login.</p>${input('temporary_password','Temporary Password','','password',true)}`,async form=>{await api(`/api/admin/users/${id}/reset-password`,'POST',Object.fromEntries(new FormData(form)));message('Password reset. Share the temporary password securely.');await load();},'Reset Password');return;}
 const prompt=action==='status'?`${a.is_active?'Deactivate':'Activate'} ${a.username}? ${a.is_active?'Existing sessions will end.':''}`:action==='mfa'?`Reset MFA for ${a.username}? If MFA is required, they must enroll again.`:`Unlock ${a.username}? The failed-attempt counter and lockout will be cleared.`;open(action==='status'?'Change Account Status':action==='mfa'?'Reset MFA':'Unlock Account',`<p>${e(prompt)}</p>`,async()=>{await api('/api/admin/users/'+id+(action==='status'?'':action==='mfa'?'/reset-mfa':'/unlock'),action==='status'?'PATCH':'POST',action==='status'?{revision:a.revision,is_active:a.is_active?0:1}:{});message('Account updated.');await load();},'Confirm');}
 async function roleForm(id){const a=options.roles.find(r=>r.role_id===id),selected=options.role_permissions.filter(r=>r.role_id===id).map(r=>r.permission_id);open(a?'Edit Role':'Create Role',`${input('role_name','Role Name',a?.role_name||'','text',true)}${!a?input('role_code','Role Code (e.g. SITE_TECHNICIAN)','','text',true):''}<label>Status<select name="is_active"><option value="1" ${a?.is_active!==0?'selected':''}>Active</option><option value="0" ${a?.is_active===0?'selected':''}>Inactive</option></select></label><fieldset class="admin-section"><legend>Role Permissions</legend><div class="admin-checks">${options.permissions.map(p=>`<label><input type="checkbox" name="permission_ids" value="${p.permission_id}" ${selected.includes(p.permission_id)?'checked':''}>${e(label(p.permission_code))}</label>`).join('')}</div></fieldset>`,async form=>{const data=Object.fromEntries(new FormData(form));data.is_active=Number(data.is_active);data.permission_ids=[...form.querySelectorAll('[name=permission_ids]:checked')].map(x=>Number(x.value));await api('/api/admin/roles'+(id?'/'+id:''),id?'PATCH':'POST',data);message('Role permissions updated. Assigned users must sign in again.');await load();});}
 async function teamsForm(id){const a=options.teams.find(t=>t.team_id===id),members=id?(await api('/api/admin/teams/'+id)).members:[];open(a?'Edit Team':'Create Team',`${input('team_name','Team Name',a?.team_name||'','text',true)}<label>Department${select('departments','department_id',a?.department_id)}</label><fieldset class="admin-section"><legend>Employee Members</legend><div class="admin-checks">${options.employees.map(emp=>`<label><input name="employee_ids" type="checkbox" value="${emp.employee_id}" ${members.some(m=>m.employee_id===emp.employee_id)?'checked':''}>${e(getName(emp,'employees'))}</label>`).join('')||'<p>Create employee records before adding team members.</p>'}</div></fieldset>`,async form=>{const data=Object.fromEntries(new FormData(form));if(id)data.team_id=id;data.employee_ids=[...form.querySelectorAll('[name=employee_ids]:checked')].map(x=>Number(x.value));await api('/api/admin/teams','POST',data);message('Team saved. Team scopes now use this employee membership.');await load();});}
 async function load(){q('#admin-content').textContent='Loading…';try{options=await api('/api/admin/options');if(tab==='accounts')return await accounts();if(tab==='roles'){q('#admin-content').innerHTML=`<div class="section-heading"><h2>Role Definitions</h2><button id="create-role">Create Role</button></div>${options.roles.map(r=>`<article class="row"><div><b>${e(r.role_name)}</b><p>${e(r.role_code)} · ${r.is_active?'Active':'Inactive'}</p><p class="small">${r.role_code==='SUPER_ADMIN'?'Full access to all functions and scopes.':e(options.role_permissions.filter(x=>x.role_id===r.role_id).map(x=>label(options.permissions.find(p=>p.permission_id===x.permission_id)?.permission_code||'')).join(', ')||'No permissions')}</p></div>${r.role_code==='SUPER_ADMIN'?'':`<button data-edit-role="${r.role_id}">Edit Permissions</button>`}</article>`).join('')}`;q('#create-role').onclick=()=>roleForm();}if(tab==='teams'){q('#admin-content').innerHTML=`<div class="section-heading"><h2>Teams</h2><button id="create-team">Create Team</button></div><p class="small">Team-scoped users can access assets currently assigned to team members.</p>${options.teams.map(t=>`<article class="row"><b>${e(t.team_name)}</b><button data-edit-team="${t.team_id}">Edit Members</button></article>`).join('')||'<p>No teams created yet.</p>'}`;q('#create-team').onclick=()=>teamsForm();}if(tab==='audit'){const data=await api('/api/admin/audit');q('#admin-content').innerHTML=`<h2>Access Audit Log</h2><p class="small">Latest 100 administrative and login events. Passwords and authenticator secrets are excluded.</p><div id="audit-events">${data.events.map(eventHTML).join('')||'<p>No events recorded.</p>'}</div><button id="more-audit" ${data.events.length<100?'hidden':''}>Load Older Events</button>`;let cursor=data.events.at(-1)?.audit_id;q('#more-audit').onclick=async()=>{const next=await api('/api/admin/audit?before='+cursor);q('#audit-events').insertAdjacentHTML('beforeend',next.events.map(eventHTML).join(''));cursor=next.events.at(-1)?.audit_id;q('#more-audit').hidden=next.events.length<100;};}if(tab==='settings'){q('#admin-content').innerHTML=`<h2>Session Timeout</h2><p>Changes end all active sessions, including yours.</p><form id="session-settings"><label>Session duration in minutes<input name="session_timeout_minutes" type="number" min="5" max="1440" required value="${e(options.settings.find(s=>s.setting_key==='session_timeout_minutes')?.setting_value||480)}"></label><button class="primary">Save Timeout</button></form>`;systemControls();q('#session-settings').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/admin/settings','POST',Object.fromEntries(new FormData(ev.target)));location.replace('/login');}catch(x){message(x.message);}};}}catch(x){q('#admin-content').textContent=x.message;}}
 q('#create-user').onclick=async()=>{try{if(!options)options=await api('/api/admin/options');await editUser();}catch(x){message(x.message);}};q('#user-close').onclick=()=>q('#user-dialog').close();q('#user-form').onsubmit=async ev=>{ev.preventDefault();if(!submit)return;q('#user-save').disabled=true;q('#user-error').hidden=true;try{await submit(ev.target);q('#user-dialog').close();}catch(x){q('#user-error').textContent=x.message;q('#user-error').hidden=false;}finally{q('#user-save').disabled=false;}};
 document.addEventListener('jmdm:pagechange',async ev=>{if(ev.detail?.page==='users')await load();});if(!q('#users').hidden)load();
 document.addEventListener('change',async ev=>{if(ev.target.dataset.feature){try{await api('/api/admin/features','POST',{feature:ev.target.dataset.feature,enabled:ev.target.checked});message('System feature updated and logged.');}catch(x){ev.target.checked=!ev.target.checked;message(x.message);}} if(ev.target.matches('[data-scope-type]'))scopeReferences(ev.target.closest('.scope-row'));if(q('#permission-preview')&&(ev.target.name==='role_ids'||ev.target.matches('[data-permission]')))preview();});
 document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.dataset.page==='users')await load();if(b.dataset.adminTab){tab=b.dataset.adminTab;q('.admin-tabs').querySelectorAll('button').forEach(x=>x.setAttribute('aria-selected',String(x===b)));q('#create-user').hidden=tab!=='accounts';await load();}if(b.hasAttribute('data-remove-scope'))b.closest('.scope-row').remove();if(b.dataset.userAction)await userAction(b.dataset.userAction,Number(b.dataset.user));if(b.dataset.editRole)await roleForm(Number(b.dataset.editRole));if(b.dataset.editTeam)await teamsForm(Number(b.dataset.editTeam));}catch(x){message(x.message);}});
})();
